use serde::Deserialize;
use std::collections::BTreeMap;

#[derive(Clone, Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RawConfig {
    pub changesets: Option<RawChangesetsConfig>,
    pub cascade: Option<RawCascadeConfig>,
    pub validation: Option<RawValidationConfig>,
    pub release: Option<RawProductReleaseConfig>,
    pub registries: Option<BTreeMap<String, RawRegistryConfig>>,
    pub package: Option<Vec<RawPackageConfig>>,
    #[serde(rename = "package-set")]
    pub package_set: Option<Vec<RawPackageSetConfig>>,
    #[serde(rename = "fixed-group")]
    pub fixed_group: Option<Vec<crate::config::groups::RawGroup>>,
    #[serde(rename = "linked-group")]
    pub linked_group: Option<Vec<crate::config::groups::RawGroup>>,
}

/// Product binary release declaration. Credentials and provider endpoints are
/// intentionally excluded: this configuration only identifies immutable
/// intent slots; execution receives credentials from its caller.
#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RawProductReleaseConfig {
    #[serde(rename = "product-package")]
    pub product_package: String,
    /// Binary artifacts attached to the product's forge release. Each names the
    /// package that builds it, so an artifact need not come from the product.
    #[serde(default)]
    pub artifact: Vec<RawArtifactConfig>,
    /// The GitHub repository (`owner/repo`) the product release publishes to.
    #[serde(rename = "forge-repository")]
    pub forge_repository: Option<String>,
}

/// One declared release artifact. `target` is opaque to Callisto: it is passed
/// through to whatever builds the bytes, never parsed.
#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RawArtifactConfig {
    pub package: String,
    pub target: String,
    #[serde(rename = "asset-name")]
    pub asset_name: String,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RawChangesetsConfig {
    /// Workspace-root-relative. Always forward-slash-separated (`/`), never `\`, regardless
    /// of the OS this value was authored or is read on — `\` is a legal filename character
    /// on POSIX, not a separator, so a backslash-separated value would silently name a
    /// single oddly-named directory rather than a nested path the moment this file is read
    /// on a non-Windows host. Rejected if absolute or containing `..` components
    /// (`ConfigError::InvalidChangesetsDir`, E116).
    pub dir: Option<String>,
}

#[derive(Clone, Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RawCascadeConfig {
    pub mode: Option<String>,
    #[serde(rename = "bump-severity")]
    pub bump_severity: Option<String>,
    #[serde(rename = "peer-escalation")]
    pub peer_escalation: Option<bool>,
    #[serde(rename = "preserve-npm-ranges")]
    pub preserve_npm_ranges: Option<bool>,
}

#[derive(Clone, Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RawValidationConfig {
    #[serde(rename = "allow-empty-changesets")]
    pub allow_empty_changesets: Option<bool>,
}

#[derive(Clone, Debug, Deserialize)]
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use callisto_model::release::is_safe_artifact_component;
use callisto_model::{
    ConfigKey, Ecosystem, GitHubRepository, PackageId, PublishTarget, RegistryKey, ReleaseTrigger, Severity,
    TagTemplate,
};

use crate::config::groups::{GroupTable, RawGroupTable};
use crate::config::pattern::PackagePattern;
use crate::config::raw::{RawConfig, RawProductReleaseConfig};
use crate::error::ConfigError;

#[derive(Clone, Debug)]
pub struct ResolvedConfig {
    pub root: PathBuf,
    pub changesets_dir: PathBuf,
    pub cascade: CascadeConfig,
    pub validation: ValidationConfig,
    pub product_release: Option<ProductReleaseConfig>,
    pub registries: BTreeMap<RegistryKey, RegistryConfig>,
    /// Per-package override rules from `[[package]]` blocks, in TOML declaration order. Every rule is
    /// ecosystem-qualified; the first one that applies to a package wins (see `resolve_package_config`).
    pub packages: Vec<(PackageId, PackageConfig)>,
    /// Bulk config-override rules from `[[package-set]]` blocks, in TOML declaration order.
    /// Applied as a fallback when no `[[package]]` rule matches a package.
    /// Unlike `[[package]]` (exact `PackageId` match, first-wins), each
    /// `[[package-set]]` rule uses a glob pattern and can match many packages simultaneously.
    pub package_sets: Vec<(PackagePattern, PackageConfig)>,
    pub groups: GroupTable,
    /// Raw group declarations from `callisto.toml`, kept so that
    /// `Workspace::load` can call `GroupTable::resolve` once the
    /// `IdentityIndex` is available after `ManifestWalkResolver::build`.
    pub(crate) raw_groups: RawGroupTable,
    provenance: BTreeMap<ConfigKey, ConfigProvenance>,
}

/// Credential-free declaration of the one product that owns GitHub binary
/// assets. The operation builder supplies the immutable attestation policy.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductReleaseConfig {
    pub package: PackageId,
    pub artifacts: Vec<ProductArtifactConfig>,
    /// The one forge destination; planning requires it.
    pub forge_repository: Option<GitHubRepository>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ConfigProvenance {
    Default,
    Explicit,
}

impl ResolvedConfig {
    pub fn provenance(&self, key: &ConfigKey) -> ConfigProvenance {
        self.provenance.get(key).copied().unwrap_or(ConfigProvenance::Default)
    }

    /// The workspace-relative path to `pre.json`, inside `[changesets] dir`. The single source of truth for this
    /// path: `pre enter`/`pre exit`, `version`'s read and delete, and `apply_version_plan`'s write all resolve it
    /// through this method rather than re-deriving it.
    pub fn pre_json_path(&self) -> PathBuf {
        self.changesets_dir.join("pre.json")
    }

    pub fn rendered_value(&self, key: &ConfigKey) -> Option<String> {
        if key == &ConfigKey::CASCADE_MODE {
            Some(match self.cascade.mode {
                CascadeMode::OutOfRange => "out-of-range".to_string(),
                CascadeMode::Always => "always".to_string(),
            })
        } else if key == &ConfigKey::CASCADE_BUMP_SEVERITY {
            Some(match self.cascade.bump_severity {
                CascadeBumpSeverity::Patch => "patch".to_string(),
                CascadeBumpSeverity::Minor => "minor".to_string(),
            })
        } else if key == &ConfigKey::CASCADE_PEER_ESCALATION {
            Some(self.cascade.peer_escalation.to_string())
        } else if key == &ConfigKey::CASCADE_PRESERVE_NPM_RANGES {
            Some(self.cascade.preserve_npm_ranges.to_string())
        } else if key == &ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS {
            Some(self.validation.allow_empty_changesets.to_string())
        } else {
            None
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CascadeConfig {
    pub mode: CascadeMode,
    pub bump_severity: CascadeBumpSeverity,
    pub peer_escalation: bool,
    pub preserve_npm_ranges: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CascadeMode {
    OutOfRange,
    Always,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CascadeBumpSeverity {
    Patch,
    Minor,
}

impl CascadeBumpSeverity {
    if cascade_raw.peer_escalation.is_some() {
        provenance.insert(ConfigKey::CASCADE_PEER_ESCALATION, ConfigProvenance::Explicit);
    }

    let preserve_npm_ranges = cascade_raw.preserve_npm_ranges.unwrap_or(true);
    if cascade_raw.preserve_npm_ranges.is_some() {
        provenance.insert(ConfigKey::CASCADE_PRESERVE_NPM_RANGES, ConfigProvenance::Explicit);
    }

    let validation_raw = raw.validation.unwrap_or_default();
    let allow_empty_changesets = validation_raw.allow_empty_changesets.unwrap_or(false);
    if validation_raw.allow_empty_changesets.is_some() {
        provenance.insert(ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS, ConfigProvenance::Explicit);
    }

    let mut registries = BTreeMap::new();
    registries.insert(
        RegistryKey(RegistryKey::CRATES_IO.to_string()),
        RegistryConfig {
            kind: Ecosystem::Cargo,
            url: None,
            publish_url: None,
            confirm_timeout: None,
            publish_timeout: None,
        },
    );

        package_sets.push((pattern, cfg));
    }

    Ok(ResolvedConfig {
        root: root.to_path_buf(),
        changesets_dir,
        cascade: CascadeConfig {
            mode,
            bump_severity,
            peer_escalation,
            preserve_npm_ranges,
        },
        validation: ValidationConfig { allow_empty_changesets },
        product_release,
        registries,
        packages,
        package_sets,
        groups: GroupTable::default(),
        raw_groups,
        provenance,
    })
}

