                path,
                message: error.to_string(),
            })
        }
    };
    Ok(match crate::changelog::find_section(&content, version) {
        None => Err(NotesFallback::SectionMissing),
        Some("") => Err(NotesFallback::SectionEmpty),
        Some(section) => Ok(section.to_owned()),
    })
}

