                Some("## 1.0.0\n\n- Shared change.\n- B only.\n- Joined the `lockstep` group at this version.\n"),
            ),
            ("cargo/c", Some("## 1.0.0\n\n- B only.\n")),
        ]);
        assert_eq!(
            notes,
            ReleaseNotes::Section("- Shared change.\n- A only.\n- `cargo/b`: B only.".to_owned())
        );
    }

