        );
    }

    #[test]
    fn the_owners_headings_and_paragraphs_survive_a_mates_entries() {
        let owner = "## 1.0.0\n\nIntro paragraph.\n\n### Fixes\n\n- A fix.\n- Released together with the `lockstep` \
                     fixed group.\n\nClosing words.\n";
